import sys

def solve():
    raw_input = sys.stdin.read()
    if not raw_input:
        return

    lines = []
    current_line_chars = []

    i = 0
    n = len(raw_input)

    while i < n:
        if raw_input[i] == '\r':
            if i + 1 < n and raw_input[i+1] == '\n':
                i += 2
            else:
                i += 1
            lines.append("".join(current_line_chars))
            current_line_chars = []
        elif raw_input[i] == '\n':
            i += 1
            lines.append("".join(current_line_chars)) 
            current_line_chars = []
        else:
            current_line_chars.append(raw_input[i])
            i += 1

    if current_line_chars:
        lines.append("".join(current_line_chars))

    if not lines:
        return

    result_lines = []
    buffer = []

    def is_amplifying(line):
        stripped = line.lstrip()
        return len(stripped) > 0 and stripped[0] == '#'

    def process_line(line, is_amp):
        if is_amp:
            return line
        else:
            return line.replace(' ', '')

    i = 0
    while i < len(lines):
        line = lines[i]
        is_amp = is_amplifying(line)

        if is_amp:
            if buffer:
                result_lines.append("".join(buffer))
                buffer = []
            result_lines.append(process_line(line, is_amp))
            i += 1
        else:
            buffer.append(process_line(line, is_amp))
            i += 1

    if buffer:
        result_lines.append("".join(buffer))

    output = "\n".join(result_lines)
    if output:
        print(output)

if __name__ == "__main__":
    solve()
